const MULTI = ['Yamaha PSR-730', 'Alesis Micron'];

function canStack(s, u) {
  return MULTI.includes(s) || !u.some(l => l.synth === s);
}

function getStacked(cat, syn, num) {
  let all = PATCHES[cat] || [];
  if (syn !== 'random') all = all.filter(p => p.synth === syn);
  if (!all.length) all = PATCHES[cat] || [];
  let layers = [], used = new Set();
  for (let i = 0; i < num; i++) {
    let avail = all.filter(p => !used.has(p.name) && canStack(p.synth, layers));
    if (!avail.length) avail = all.filter(p => !used.has(p.name));
    if (!avail.length) break;
    const p = avail[Math.floor(Math.random() * avail.length)];
    layers.push(p);
    used.add(p.name);
  }
  return layers;
}

function buildRandom() {
  return [
    { category: 'bass',       layers: getStacked('bass',       'random', 1) },
    { category: 'lead',       layers: getStacked('lead',       'random', 1) },
    { category: 'pad',        layers: getStacked('pad',        'random', 1) },
    { category: 'percussion', layers: getStacked('percussion', 'random', 1) },
  ];
}

function buildChill() {
  return [
    { category: 'pad',  layers: getStacked('pad',  'random', 2) },
    { category: 'keys', layers: getStacked('keys', 'random', 1) },
    { category: 'bass', layers: getStacked('bass', 'random', 1) },
  ];
}

function buildAggressive() {
  return [
    { category: 'bass',       layers: getStacked('bass',       'random', 2) },
    { category: 'lead',       layers: getStacked('lead',       'random', 2) },
    { category: 'percussion', layers: getStacked('percussion', 'random', 1) },
  ];
}

function buildMinimal() {
  return [
    { category: 'bass', layers: getStacked('bass', 'random', 1) },
    { category: 'lead', layers: getStacked('lead', 'random', 1) },
  ];
}

function buildFullOrchestra() {
  return [
    { category: 'symphony',   layers: getStacked('symphony',   'random', 2) },
    { category: 'vocal',      layers: getStacked('vocal',      'random', 1) },
    { category: 'percussion', layers: getStacked('percussion', 'random', 1) },
  ];
}

function buildChamber() {
  return [
    { category: 'symphony', layers: getStacked('symphony', 'random', 1) },
    { category: 'keys',     layers: getStacked('keys',     'random', 1) },
  ];
}

function buildStrings() {
  return [
    { category: 'symphony', layers: getStacked('symphony', 'random', 3) },
  ];
}

module.exports = {
  PATCHES,
  MULTI,
  canStack,
  getStacked,
  buildRandom,
  buildChill,
  buildAggressive,
  buildMinimal,
  buildFullOrchestra,
  buildChamber,
  buildStrings,
};
